<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; require_once __DIR__.'/../includes/auth.php'; requireRole(['author']);
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Invalid article.');}
$q=$pdo->prepare('SELECT title FROM articles WHERE id=?');$q->execute([$id]);$article=$q->fetch();if(!$article){http_response_code(404);exit('Article not found.');}
$q=$pdo->prepare('SELECT r.*,u.username FROM article_revisions r LEFT JOIN users u ON u.id=r.user_id WHERE r.article_id=? ORDER BY r.created_at DESC LIMIT 100');$q->execute([$id]);$revisions=$q->fetchAll();$pageTitle='Article History';require_once __DIR__.'/../includes/header.php';
?>
<div class="container py-5"><h1 class="h2">Editorial history</h1><p class="text-muted"><?= e($article['title']) ?></p><a class="btn btn-outline-secondary mb-3" href="<?= e(url('admin/edit_article.php?id='.$id)) ?>">Back to article</a><?php if(!$revisions): ?><div class="alert alert-info">No revisions have been recorded yet. Changes made after installing the editorial migration will be recorded.</div><?php endif; ?><?php foreach($revisions as $r): ?><div class="card mb-3"><div class="card-header d-flex justify-content-between"><strong><?= e($r['change_summary']?:'Saved revision') ?></strong><span><?= e($r['created_at']) ?> · <?= e($r['username']??'Former user') ?></span></div><div class="card-body"><h5><?= e($r['title']) ?></h5><p><?= nl2br(e($r['excerpt']??'')) ?></p><details><summary>View saved content</summary><div class="mt-3"><?= nl2br(e($r['content']??'')) ?></div></details><small class="text-muted">Status at revision: <?= e($r['status']) ?></small></div></div><?php endforeach; ?></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
